#!/usr/bin/env node
// Generates /_redirects (static 301s) for Workers static assets.
// Replaces the path redirects that worker.js used to do with run_worker_first: true.
// Rerun after adding or removing any .html page:  node tests/gen-redirects.cjs
const fs = require("fs");
const path = require("path");
const root = path.resolve(__dirname, "..");
const lines = [
  "# Generated by tests/gen-redirects.cjs. Do not edit by hand; rerun the script.",
  "# Static 301s only (relative paths). Host-level www->apex and http->https are",
  "# Cloudflare dashboard rules (Redirect Rules + Always Use HTTPS), not this file.",
  "",
  "# Legacy salary-guide slugs -> series URLs (one hop, incl. old .html and slash forms)",
];
// Salary guides folded into the take-home pay table on 13 November 2026.
const TABLE = "/guides/salary-table";
const merged = ["take-home-20000", "take-home-22000", "take-home-28000", "take-home-32000", "take-home-45000",
  "take-home-55000", "take-home-65000", "take-home-70000", "take-home-75000", "take-home-90000",
  "scotland-28000", "scotland-35000", "scotland-40000", "scotland-55000"];
for (const k of [25, 30, 35, 40, 45, 50, 55, 60, 70, 75]) {
  const from = `/guides/${k}k-take-home`;
  const to = merged.includes(`take-home-${k * 1000}`) ? TABLE : `/guides/take-home-${k * 1000}`;
  lines.push(`${from} ${to} 301`, `${from}/ ${to} 301`, `${from}.html ${to} 301`);
}
lines.push("", "# Salary guides merged into the take-home pay table (one hop)");
for (const slug of merged) {
  lines.push(`/guides/${slug} ${TABLE} 301`, `/guides/${slug}/ ${TABLE} 301`, `/guides/${slug}.html ${TABLE} 301`);
}
lines.push(
  "",
  "# Google Search Console HTML verification must answer 200 at the exact .html URL.",
  "# html_handling would 307 it to the extensionless path, so proxy (200) to the file instead.",
);
for (const f of fs.readdirSync(root).filter((f) => /^google[a-z0-9]+\.html$/i.test(f)).sort()) {
  lines.push(`/${f} /${f.slice(0, -5)} 200`);
}
lines.push("", "# .html -> extensionless canonical, trailing slash -> no slash, dir index -> /dir/");
const pages = [];
(function walk(dir) {
  for (const f of fs.readdirSync(path.join(root, dir)).sort()) {
    const rel = path.posix.join(dir, f);
    if (["node_modules", ".git", ".wrangler", "tests"].includes(f)) continue;
    const st = fs.statSync(path.join(root, rel));
    if (st.isDirectory()) walk(rel);
    else if (f.endsWith(".html") && !/^google[a-z0-9]+\.html$/i.test(f)) pages.push("/" + rel.replace(/^\.\//, ""));
  }
})(".");
for (const p of pages) {
  const noext = p.slice(0, -5);
  if (noext === "/index") {
    lines.push("/index.html / 301", "/index / 301");
  } else if (noext.endsWith("/index")) {
    const dir = noext.slice(0, -5); // "/guides/"
    lines.push(`${dir.slice(0, -1)} ${dir} 301`, `${noext} ${dir} 301`, `${p} ${dir} 301`);
  } else {
    lines.push(`${p} ${noext} 301`, `${noext}/ ${noext} 301`);
  }
}
fs.writeFileSync(path.join(root, "_redirects"), lines.join("\n") + "\n");
console.log(`wrote _redirects: ${lines.filter((l) => l && !l.startsWith("#")).length} rules`);
